text:
Preparation
The 11 study sites comprise a new compilation of longitudinal tree census records from tropical forest experiments in which defined logging treatments were imposed, and forest recovery was determined through periodic censuses on permanent plots. The sites comprises 7 sites in South America (Argentina: Misiones; Costa Rica: Tirimbina; Brazil: Iracema, Jari, Jenaro Herrera, Moju, Pad Limo; French Guian: Paracou), 1 site in Africa (Mbaiki in Central African Republic) and 1 site in Asia (SUAS in Malaysia) (Table X). The sites range in latitude from 27°S to 11°N and in longitude from 84°W to 117°E. They are characterised by a subtropical to tropical climate, with annual precipitation ranging from 1,236 to 3,640 mm and dry seasons lasting from 37 to 177 days (Abatzoglou et al. 2018). Selective logigng happened in all sites with X% sites including reduced impact logging parcatives and X% sites with additional practices (to be listed). All sites include pre-logging inventories and some ontrol and undisturbed plots (X sites). Depending on the site, plot areas range from 0.25 to 6.25 hectares, with a total sampled area ranging from X to 56 hectares (see Table X). To facilitate comparison, the plots were virtually pulled or subdivided into standard 1-hectare plots. All trees with a diameter at breast height (DBH) above 10 cm (except in Jari where the minimum DBH was 20 cm) were inventoried and then spatialised before botanical identification. Their diameters were regularly measured, with X to 28 censuses conducted over X to 18 years post-logging. The 110 study sites were selected from a larger pool of 31 sites in tropical forests. However, we focused on sites with more than one logged plot and several censuses shortly after logging, with a minimum of two censuses, and the presence of pre-logging inventories.
Chunks below help preparing the data for the analyses.
Code
library(googlesheets4)
read_sheet("https://docs.google.com/spreadsheets/d/1fq2owxMBLBwwibcdw2uQQFxnIhsMbaH4Qcj_xUwVvSQ/edit?usp=sharing", 2) |&gt; # nolint
  separate_rows(site_raw, sep = ",") |&gt;
  write_tsv("data/raw_data/sites.tsv")
read_sheet("https://docs.google.com/spreadsheets/d/1fq2owxMBLBwwibcdw2uQQFxnIhsMbaH4Qcj_xUwVvSQ/edit?gid=0#gid=0", col_types = "c") |&gt; # nolint
  rename_all(tolower) |&gt;
  select(site, plot, treatment, year_of_harvest, longitude) |&gt;
  write_tsv("data/raw_data/metadata.tsv")
read_sheet("https://docs.google.com/spreadsheets/d/1fq2owxMBLBwwibcdw2uQQFxnIhsMbaH4Qcj_xUwVvSQ/edit?usp=sharing",
  "plot_correspondance",
  col_types = "c"
) |&gt;
  write_tsv("data/raw_data/plot_metadata.tsv")
read_sheet("https://docs.google.com/spreadsheets/d/1fq2owxMBLBwwibcdw2uQQFxnIhsMbaH4Qcj_xUwVvSQ/edit?usp=sharing",
  "spurious",
  col_types = "c"
) |&gt;
  na.omit() |&gt;
  write_tsv("data/raw_data/spurious.tsv")
Code
metadata &lt;- read_tsv("data/raw_data/metadata.tsv") |&gt;
  rename(site_raw = site) |&gt;
  left_join(read_tsv("data/raw_data/sites.tsv")) |&gt;
  select(-site_raw) |&gt;
  separate(year_of_harvest, "year_of_harvest") |&gt;
  mutate(year_of_harvest = as.numeric(year_of_harvest)) |&gt;
  rename(harvest_year = year_of_harvest) |&gt;
  mutate(treatment = ifelse(treatment == "Control", "control", "logged")) |&gt;
  group_by(site) |&gt;
  mutate(harvest_year_min = min(harvest_year, na.rm = TRUE)) |&gt;
  mutate(harvest_year = ifelse(site == "Paracou", 1986, harvest_year)) |&gt;
  mutate(harvest_year_min = ifelse(site == "Paracou", 1986, harvest_year_min))
vars &lt;- c("ba", "diversity_q0_sp", "diversity_q0_sp_rar", "p_undet_spp")
sites &lt;- c(
  "Iracema", "Jari", "Jenaro Herrera", "Mbaiki", "Misiones", "Moju",
  "Pad Limo 2 Barracos", "Pad Limo Chico Bocao", "Pad Limo Cumaru",
  "Pad Limo Jatoba", "Pad Limo Pocao", "Pad Limo STCP",
  "Paracou", "Tapajos Km114", "Tirimbina", "SUAS"
  # "SUAS", # removed until diversity_q0_sp_rar is not computed in v10
)
pad_sites &lt;- c(
  "Pad Limo 2 Barracos", "Pad Limo Chico Bocao", "Pad Limo Cumaru",
  "Pad Limo Jatoba", "Pad Limo Pocao", "Pad Limo STCP"
)
spurious &lt;- read_tsv("data/raw_data/spurious.tsv")
data &lt;- read_csv("data/raw_data/aggregated_data_v10.csv") |&gt;
  na.omit() |&gt;
  rename_all(tolower) |&gt;
  rename(site_raw = site) |&gt;
  left_join(read_tsv("data/raw_data/sites.tsv")) |&gt;
  select(-site_raw) |&gt;
  rename(new_plot = plot) |&gt;
  left_join(read_tsv("data/raw_data/plot_metadata.tsv")) |&gt;
  left_join(metadata) |&gt;
  select(-plot) |&gt;
  rename(plot = new_plot, area = new_plot_area) |&gt;
  filter(site %in% sites) |&gt;
  filter(!(site %in% spurious$site &
    plot %in% spurious$plot &
    year %in% spurious$year)) |&gt;
  mutate(plot = ifelse(site %in% pad_sites,
    paste(site, plot),
    plot
  )) |&gt;
  mutate(site = ifelse(site %in% pad_sites, "Pad Limo", site)) |&gt;
  filter(variable %in% vars) |&gt;
  mutate(rel_year = ifelse(treatment == "control",
    year - harvest_year_min,
    year - harvest_year
  )) |&gt;
  pivot_wider(names_from = variable, values_from = value) |&gt;
  filter(treatment == "logged") |&gt;
  select(-longitude, harvest_year_min)
dist_obs &lt;- data |&gt;
  filter(rel_year &gt; 0) |&gt;
  group_by(site, plot) |&gt;
  summarise(ba_post = min(ba, na.rm = TRUE)) |&gt;
  left_join(data %&gt;%
    filter(rel_year &lt;= 0) |&gt;
    group_by(site, plot) |&gt;
    summarise(ba_pre = median(ba, na.rm = TRUE))) |&gt;
  mutate(dist_obs = (ba_pre - ba_post) / ba_pre) |&gt;
  select(site, plot, dist_obs) |&gt;
  mutate(dist_obs = ifelse(dist_obs &lt; 0, 0, dist_obs))
data |&gt;
  left_join(dist_obs) |&gt;
  filter(dist_obs &gt; 0) |&gt; 
  mutate(sitenum = as.numeric(as.factor(site))) |&gt;
  mutate(plotnum = as.numeric(as.factor(paste0(site, "_", plot)))) |&gt;
  write_tsv("data/derived_data/data.tsv")

Paracou
Paracou plots are 6.25-ha 250x250m plots, we subdivided them into 4-ha, 2-ha, 1-ha, 0.5-ha and 0.25-ha.


Code
paracou &lt;- "data/raw_data/data_cleaned_paracou.csv" |&gt;
  read_csv() |&gt;
  rename_all(tolower) |&gt;
  rename(x = xtreeplot, y = ytreeplot) |&gt;
  # 6.25-ha
  mutate(plot_625 = plot) |&gt;
  select(site, plot, idtree, x, y, plot_625) |&gt;
  unique() |&gt;
  # 4-ha
  mutate(
    subx = ifelse(x &lt;= 200, x, NA),
    suby = ifelse(y &lt;= 200, y, NA)
  ) |&gt;
  rowwise() |&gt;
  mutate(plot_400 = ifelse(!is.na(subx) && !is.na(suby),
    paste0(plot_625, "_1"), NA
  )) |&gt;
  # 2-ha
  mutate(plot_200 = ifelse(subx &gt; 100, paste0(plot_400, "_2"),
    paste0(plot_400, "_1")
  )) |&gt;
  mutate(subx = ifelse(subx &gt; 100, subx - 100, subx)) |&gt;
  # 1-ha
  mutate(plot_100 = ifelse(suby &gt; 100, paste0(plot_200, "_2"),
    paste0(plot_200, "_1")
  )) |&gt;
  mutate(suby = ifelse(suby &gt; 100, suby - 100, suby)) |&gt;
  # 0.5-ha
  mutate(plot_050 = ifelse(subx &gt; 50, paste0(plot_100, "_2"),
    paste0(plot_100, "_1")
  )) |&gt;
  mutate(subx = ifelse(subx &gt; 50, subx - 50, subx)) |&gt;
  # 0.25-ha
  mutate(plot_025 = ifelse(suby &gt; 50, paste0(plot_050, "_2"),
    paste0(plot_050, "_1")
  )) |&gt;
  mutate(suby = ifelse(suby &gt; 50, suby - 50, suby)) |&gt;
  select(-subx, -suby) |&gt;
  mutate(across(
    c("plot_200", "plot_100", "plot_050", "plot_025"),
    ~ ifelse(is.na(plot_400), NA, .)
  )) |&gt;
  gather(area, subplot, -site, -plot, -idtree, -x, -y) |&gt;
  separate(area, c("x1", "area"), convert = TRUE) |&gt;
  select(-x1) |&gt;
  mutate(area = area / 100)
write_tsv(paracou, "data/derived_data/paracou_subplots.tsv")




